CREATE TABLE DiscountCode (id VARCHAR(191) NOT NULL PRIMARY KEY,code VARCHAR(191) NOT NULL,percent INT NOT NULL,active BOOLEAN NOT NULL DEFAULT true,maxUses INT NULL,used INT NOT NULL DEFAULT 0,expiresAt DATETIME(3) NULL,createdAt DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE KEY DiscountCode_code_key(code)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE Checkout ADD COLUMN discount INT NOT NULL DEFAULT 0, ADD COLUMN discountCode VARCHAR(191) NULL;
ALTER TABLE `Order` ADD COLUMN discount INT NOT NULL DEFAULT 0;
ALTER TABLE SupportTicket ADD COLUMN attachment MEDIUMTEXT NULL;
